"""One-off: rows for naming status and sport counts found in the 17 Nov 2026 research pass.
Writes data/research/verification_zzzzzzzzz_venues_sports.csv. Run after merge_research.py so current blanks are known."""
import csv,re
D='2026-11-17'
M=list(csv.DictReader(open('data/merged_values.csv',encoding='utf-8')))
V={(r['school'],r['metric']):r for r in M}
rows=[]
def add(school,metric,value,season,src,url,note,unit=None):
    unit=unit or ('USD' if metric.endswith('_value') else 'years' if metric.endswith('term_years') else 'year' if metric.endswith('_year') else 'count' if metric=='varsity_sports' else 'text')
    rows.append([school,metric,value,unit,season,src,url,D,note])
def named(pre,school,partner,kind,src,url,note,why=None):
    add(school,pre+'_partner',partner,'2026',src,url,note); add(school,pre+'_deal_type',kind,'2026',src,url,note)
    if kind in ('honorific','none'):
        why=why or ('honorific; no commercial fee' if kind=='honorific' else 'no naming-rights deal')
        for m in ('annual_value','total_value','term_years','start_year','industry'):
            cur=V.get((school,f'{pre}_{m}'))
            if cur is None or cur['value'] in ('--',''): add(school,f'{pre}_{m}','--','2026',src,url,why)
