WHY={('Oklahoma State','stadium_year_opened'):"the school's game notes give capacity only and its facility page could not be read",('California','stadium_year_opened'):"the school's game notes say the stadium celebrated 103 years in 2026 but do not print the year",('TCU','arena_year_opened'):"no page stating the year could be read",('Florida State','arena_year_opened'):"only a stadium-review site gives a year (1981); the venue's own site does not",
 ('Nebraska','stadium_capacity'):"the official page says only ‘beyond 85,000’; an exact figure (85,458) appears on a stadium-review site only",
 ('BYU','stadium_last_renovation_year'):"the school lists a 1982 expansion and smaller upgrades through 2024 without naming a latest major renovation",('Baylor','stadium_last_renovation_year'):"no major renovation since the stadium opened in 2014; an enhancement project ran over the 2024 and 2025 offseasons",('Houston','stadium_last_renovation_year'):"the football operations center beside the stadium was completed in August 2025; the stadium itself opened in 2014 and no renovation of it is stated",
 ('Minnesota','stadium_last_renovation_year'):"the school's game notes list no renovation since the stadium's first season in 2009",('Pittsburgh','stadium_last_renovation_year'):"Acrisure Stadium is the Pittsburgh Steelers' stadium; its site describes a south end expansion in 2015 without calling it the latest renovation",
 ('Louisville','stadium_last_renovation_year'):"no page stating the year could be read",('NC State','stadium_last_renovation_year'):"no page stating the year could be read",('Wake Forest','stadium_last_renovation_year'):"no page stating the year could be read",('West Virginia','stadium_last_renovation_year'):"the school's game notes give the opening year only",('Nebraska','stadium_last_renovation_year'):"an east stadium expansion in the early 2010s is described without an exact year in any official page read"}
pat=re.compile(r'budget|research effort|exhaust|Withdrawn',re.I)
for (s,m),why in WHY.items():
    cur=V.get((s,m))
    if cur is not None and cur['value'] in ('--','') and pat.search(cur['notes']): add(s,m,'--','2026','searched 17 Nov 2026','',f"Searched on 17 Nov 2026 and not confirmed: {why}.",unit='year' if 'year' in m else 'seats')
with open('data/research/verification_zzzzzzzzz_venues_sports.csv','w',newline='',encoding='utf-8') as fh:
    w=csv.writer(fh); w.writerow(['school','metric','value','unit','fiscal_year_or_season','source_name','source_url','date_accessed','notes']); w.writerows(rows)
print('rows',len(rows),'| value rows',sum(1 for r in rows if r[2]!='--'))
